<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require_permission('media.manage');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();if(($_POST['action']??'')==='delete'){$st=$pdo->prepare('SELECT file_path FROM media_library WHERE id=?');$st->execute([(int)$_POST['id']]);$p=$st->fetchColumn();if($p&&str_starts_with((string)$p,'uploads/media/'))@unlink(ROOT_DIR.'/'.$p);$pdo->prepare('DELETE FROM media_library WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Archivo eliminado.');}else{$f=$_FILES['file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Selecciona un archivo válido.');if((int)$f['size']>8*1024*1024)throw new RuntimeException('El archivo no puede superar 8 MB.');$mime=secure_file_mime_type($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new RuntimeException('Formato permitido: JPG, PNG, WEBP o PDF.');$dir=UPLOAD_DIR.'/media';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('No se pudo guardar el archivo.');$pdo->prepare('INSERT INTO media_library(file_path,original_name,mime_type,file_size,alt_text) VALUES(?,?,?,?,?)')->execute(['uploads/media/'.$name,basename((string)$f['name']),$mime,(int)$f['size'],trim((string)($_POST['alt_text']??''))]);flash('success','Archivo agregado a la biblioteca.');}header('Location: media.php');exit;}catch(Throwable $e){flash('error',$e->getMessage());header('Location: media.php');exit;}}
$rows=$pdo->query('SELECT * FROM media_library ORDER BY id DESC')->fetchAll();$pageTitle='Media Library';$active='media';require __DIR__.'/_header.php';?>
