<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Vista</th><th>Archivo</th><th>Tamaño</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php if(str_starts_with($r['mime_type'],'image/')):?><img class="preview-thumb" src="../<?=h($r['file_path'])?>" alt=""><?php else:?>PDF<?php endif;?></td><td><a href="../<?=h($r['file_path'])?>" target="_blank"><?=h($r['original_name'])?></a><br><small><?=h($r['alt_text'])?></small></td><td><?=number_format($r['file_size']/1024,1)?> KB</td><td><div class="actions"><a class="button secondary small" href="../<?=h($r['file_path'])?>" target="_blank" rel="noopener">Ver</a><form method="post" data-premium-confirm data-confirm-title="Eliminar archivo" data-confirm-message="¿Eliminar este archivo? Esta acción no se puede deshacer." data-confirm-ok="Sí, eliminar" data-confirm-cancel="Cancelar"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger small">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>
